import { createEffect, createMemo, createSignal, For, on, onCleanup, onMount, Show, type Component } from "solid-js";

import { FxsNavHelp } from "#core/ui/components/fxs-nav-help.js";
import ContextManager, { ContextManagerEvents } from "#core/ui/context-manager/context-manager.js";
import ActionHandler from "#core/ui/input/action-handler.js";
import { ActiveDeviceTypeChangedEventName } from "#core/ui/input/input-events.js";
import { InputEngineEvent, NavigateInputEvent } from "#core/ui/input/input-support.js";
import Panel from "#core/ui/panel-support.js";
import ViewManager from "#core/ui/views/view-manager.js";
import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { AudioContextProvider } from "#core/ui-next/components/audio-context-provider.jsx";
import { Button } from "#core/ui-next/components/button.jsx";
import { defineLegacyComponent } from "#core/ui-next/components/fxs-solid-component.js";
import { InnerFrame } from "#core/ui-next/components/inner-frame.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { MinusPlusButton } from "#core/ui-next/components/minus-plus-button.jsx";
import { NavHelp } from "#core/ui-next/components/nav-help.jsx";
import { HSlot, Slot } from "#core/ui-next/components/slot.jsx";
import { TooltipModel } from "#core/ui-next/components/tooltip-model.js";
import { Tooltip, TooltipNavigationRules } from "#core/ui-next/components/tooltip.jsx";
import { useAudio } from "#core/ui-next/services/audio-support.js";
import { FocusManager } from "#core/ui-next/services/focus-manager.js";
import { FocusContextProvider, useFocusContext } from "#core/ui-next/services/focus.js";
import { ActiveInputDevice, IsControllerActive } from "#core/ui-next/services/input.js";
import { ComponentUtilities } from "#core/ui-next/utilities/component-utilities.js";

import {
	LowerCalloutEvent,
	TutorialCalloutInspectEventName,
	TutorialCalloutMinimizeEventName,
} from "#base/ui/tutorial/tutorial-events.js";
import TutorialItem, {
	TutorialCalloutDefinition,
	TutorialCalloutOptionDefinition,
	TutorialCalloutType,
} from "#base/ui/tutorial/tutorial-item.js";
import TutorialManager from "#base/ui/tutorial/tutorial-manager.js";
import * as TutorialSupport from "#base/ui/tutorial/tutorial-support.js";
import WatchOutManager from "#base/ui/watch-out/watch-out-manager.js";
import { SetIsPlotTooltipVisible } from "#base/ui-next/tooltips/plot-tooltip/plot-tooltip.jsx";

import style from "#base/ui/tutorial/tutorial-callout.scss?url";

type Attrs = Readonly<Record<string, string | null>>;

function parseJSON<T>(v: string | null | undefined, fallback: T): T {
	if (!v) return fallback;
	try {
		return JSON.parse(v) as T;
	} catch {
		return fallback;
	}
}

const CalloutOption: Component<{
	order: number;
	definition: TutorialCalloutOptionDefinition | undefined;
	onInteraction: () => void;
	onActivate: (optionNum: number, definition: TutorialCalloutOptionDefinition | null) => void;
}> = (props) => {
	const order = createMemo(() => props.order ?? 0);
	const definition = createMemo(() => props.definition ?? null);
	const caption = createMemo(() => props.definition?.text ?? "");
	const hotkey = createMemo(() => props.definition?.actionKey ?? "");
	const hasInteractibility = createMemo(() => hotkey().length > 0);

	createEffect(() => {
		if (hasInteractibility()) {
			props.onInteraction();
		}
	});

	return (
		<Show when={definition() != null}>
			<AudioContextProvider segment="TutorialPopup">
				<Button
					class={`tutorial-callout-button tutorial-callout-option${order()} p-6 relative leading-none break-words max-h-14 max-w-80 mb-2`}
					classList={{
						"trigger-nav-help": hasInteractibility(),
					}}
					hotkeyAction={hotkey()}
					onActivate={() => {
						props.onActivate(order(), definition());
					}}
				>
					<NavHelp class="relative mr-2" />
					{caption()}
				</Button>
			</AudioContextProvider>
		</Show>
	);
};

const TutorialCallout: Component<{
	attrs: Attrs;
	el: Element;
}> = (props) => {
	let root!: HTMLDivElement;
	const isMinimizeDisabled = createMemo(() => props.el.getAttribute("minimize-disabled") == "true");
	const id = createMemo(() => props.attrs["itemID"] ?? "");
	const value = createMemo(() => {
		const propsValue: TutorialCalloutDefinition | null =
			parseJSON<TutorialCalloutDefinition | null>(props.attrs["value"], null) ?? null;
		if (propsValue == null) {
			throw Error("tutorial-callout: There's no body information to build the callout.");
		}
		return propsValue;
	});

	const isWatchOut = createMemo(() => value()?.type == TutorialCalloutType.NOTIFICATION);
	const handheld = createMemo(() => UI.getViewExperience() == UIViewExperience.Handheld);
	const title = createMemo(() => value().title);
	const options = createMemo(() => [value().option1, value().option2, value().option3]);
	const hasOptions = createMemo(() => options().some((option) => option != undefined));

	const audioTrigger = useAudio("TutorialPopup");

	const [focusSet, setFocusSet] = createSignal(false);

	const [isClosed, setIsClosed] = createSignal(false);
	const [selectedOptionNum, setSelectedOptionNum] = createSignal(0);
	const [nextID, setNextID] = createSignal("");
	const [isMinimized, setIsMinimized] = createSignal(false);
	const [maximizeCaption, setMaximizeCaption] = createSignal("LOC_TUTORIAL_REOPEN_KBM");

	// ==== Tooltip-y variables ================
	const tooltipModel = TooltipModel.get();
	const [isInspecting, setIsInspecting] = createSignal(false);
	const [isTooltipInputChange, setIsTooltipInputChange] = createSignal(false);
	const [focusCtx, setFocusCtx] = createSignal<FocusContextProvider | null>(null);
	const isTooltipActive = createMemo(() => tooltipModel.active().length > 0 && !tooltipModel.tooltipsHidden());

	const isLocked = createMemo(() => isInspecting() || isTooltipActive());
	const isTopLevelActiveAndLocked = createMemo(() => isInspecting() && !isTooltipActive());
	// the + 1 means we always display the InspectHint because the tutorial itself behaves as one.
	const tooltipCount = createMemo(() => tooltipModel.active().length + 1);

	let slotBody!: HTMLDivElement;
	let buttons!: HTMLDivElement;
	let currentFocus = "buttons";
	// ==========================================

	const computedBodyText = () => {
		const item: TutorialItem | undefined =
			TutorialManager.getCalloutItem(id()) || WatchOutManager.currentWatchOutPopupData?.item;

		if (!item) {
			console.error(
				"tutorial-callout: getContentData(): Attempting to get tutorial item but not found, id: ",
				id(),
			);
			return;
		}

		const calloutDefine: TutorialCalloutDefinition | undefined = item.callout;
		if (!calloutDefine) {
			console.error(
				"tutorial-callout: getContentData(): Tutorial: Callout data missing; cannot raise. id: ",
				id(),
			);
			return;
		}

		let content = "";

		if (calloutDefine.body) {
			content = calloutDefine.body.text;
		}
		if (calloutDefine.body?.getLocParams) {
			TutorialManager.calloutBodyParams = calloutDefine.body.getLocParams(item);
		}

		let prompts: string[] = [];
		if (calloutDefine.actionPrompts) {
			prompts = TutorialSupport.getTutorialPrompts(calloutDefine.actionPrompts);
		}

		return Locale.stylize(content, ...TutorialManager.calloutBodyParams, ...prompts);
	};

	const computedAdvisorText = () => {
		const item: TutorialItem | undefined =
			TutorialManager.getCalloutItem(id()) || WatchOutManager.currentWatchOutPopupData?.item;

		if (!item) {
			console.error(
				"tutorial-callout: getContentData(): Attempting to get tutorial item but not found, id: ",
				id(),
			);
			return;
		}

		const calloutDefine: TutorialCalloutDefinition | undefined = item.callout;
		if (!calloutDefine) {
			console.error(
				"tutorial-callout: getContentData(): Tutorial: Callout data missing; cannot raise. id: ",
				id(),
			);
			return;
		}

		let content = "";
		if (calloutDefine.advisor?.text) {
			content = calloutDefine.advisor.text;
		}
		if (TutorialManager.calloutAdvisorParams.length <= 0 && calloutDefine.advisor?.getLocParams) {
			TutorialManager.calloutAdvisorParams = calloutDefine.advisor.getLocParams(item).filter(Boolean);
		}
		return Locale.stylize(content, ...TutorialManager.calloutAdvisorParams);
	};

	const [bodyText, setBodyText] = createSignal(computedBodyText());
	const [advisorText, setAdvisorText] = createSignal(computedAdvisorText());

	const hasTooltips = createMemo(() => bodyText()?.includes("fxs-tip") || advisorText()?.includes("fxs-tip"));
	const advisorType = createMemo(() => value().advisorType);

	const focusManager = FocusManager.get();

	const advisorURL = createMemo(() => {
		let url = "";
		if (advisorType()) {
			switch (advisorType()) {
				case "advisor-military":
					url = UI.getIconURL("ADVISOR_MILITARY");
					break;

				case "advisor-culture":
					url = UI.getIconURL("ADVISOR_CULTURE");
					break;

				case "advisor-science":
					url = UI.getIconURL("ADVISOR_SCIENCE");
					break;
				case "advisor-economic":
					url = UI.getIconURL("ADVISOR_ECONOMIC");
					break;
			}
		}
		props.el.classList.toggle("empty-advisor", url == "");

		return url;
	});

	const computeMaximizeCaption = () => {
		let caption = "LOC_TUTORIAL_REOPEN_KBM";
		switch (ActionHandler.deviceType) {
			case InputDeviceType.Controller:
				caption = "LOC_TUTORIAL_REOPEN_GAMEPAD";
				break;
			case InputDeviceType.Touch:
			case InputDeviceType.XR:
				caption = "LOC_TUTORIAL_REOPEN_TOUCH";
				break;
			default:
				break;
		}
		return caption;
	};

	createEffect(
		() => {
			props.el.classList.toggle("minimized", isMinimized());
			props.el.classList.toggle("trigger-nav-help", IsControllerActive() && !isMinimized());

			setMaximizeCaption(computeMaximizeCaption());
		},
		{ defer: true },
	);

	const onOptionInteraction = () => {
		if (!isInspecting() && !isMinimized()) {
			focusManager.setFocus(buttons);
			currentFocus = "buttons";
			lockFocus("buttons");
		}
	};

	const onOptionActivate = (optionNum: number, definition: TutorialCalloutOptionDefinition | null) => {
		if (definition?.closes && !isClosed()) {
			setSelectedOptionNum(optionNum);
			setNextID(definition.nextID || "");
			close();
		}
	};

	const onContextChanged = () => {
		if (focusSet()) {
			ViewManager.getHarness()?.classList.remove("trigger-nav-help");
		}
	};

	const onActiveDeviceChanged = () => {
		setMaximizeCaption(computeMaximizeCaption());
		setBodyText(computedBodyText());
		setAdvisorText(computedAdvisorText());
	};

	const onCalloutMinimizeToggle = () => {
		if (isInspecting()) {
			return;
		}
		const wasMinimized = isMinimized();
		if (isMinimizeDisabled()) {
			setIsMinimized(false);
		} else {
			setIsMinimized(!isMinimized());
		}

		if (isMinimized()) {
			unlockFocus("buttons");
			if (!wasMinimized) {
				audioTrigger("popup-minimize");
			}
			SetIsPlotTooltipVisible(true);
		} else {
			if (hasOptions()) {
				lockFocus("buttons");
			}
			if (wasMinimized) {
				audioTrigger("popup-maximize");
			}
			SetIsPlotTooltipVisible(false);
		}
	};

	const onCalloutInspect = () => {
		if (!hasTooltips() || isMinimized()) {
			return;
		}

		setIsInspecting(!isInspecting());
	};

	const onNavigateInput = (navigationEvent: NavigateInputEvent) => {
		const { status } = navigationEvent.detail;
		if (status != InputActionStatuses.FINISH) {
			return;
		}

		// We don't want to interact with screens if the focus is locked.
		if (FocusManager.get().isFocusLocked()) {
			navigationEvent.preventDefault();
			navigationEvent.stopImmediatePropagation();
		}
	};

	const onEngineInput = (inputEvent: InputEngineEvent) => {
		// Only process finished messages, early out to others.
		const { name, status } = inputEvent.detail;

		if (status != InputActionStatuses.FINISH) {
			return;
		}

		// Except for a call to raise the pause menu, or camera pans, consume all other input...
		if (name.startsWith("camera")) {
			return;
		} else if (name == "sys-menu") {
			// Release the lock for the pause menu
			props.el.classList.remove("trigger-nav-help");
			unlockFocus("buttons");
			return;
		} else if (
			name == "shell-action-1" ||
			name == "shell-action-3" ||
			name == "center-plot-cursor" ||
			name === "toggle-tooltip" ||
			name === "keyboard-inspect-tooltip"
		) {
			// Let the TutorialManager catch these inputs
			return;
		} else if (inputEvent.isCancelInput() && isInspecting()) {
			// make the cancel input consistent with the general tooltips
			setIsInspecting(false);
		}

		// Early out if no options take input. (May occur with KBM hotkeys)
		if (!hasOptions()) {
			if (IsControllerActive()) {
				console.error(`tutorial-callout: Attempt to handle input ${name} but callout doesn't take input.`);
			}
			return;
		}

		// Don't handle callout input when minimized
		if (isMinimized()) {
			return;
		}

		// we don't need input until all nested tooltips are closed
		if (isTooltipInputChange()) {
			return;
		}

		if (tryHandleInput(1, options()[0], inputEvent)) {
			return;
		}
		if (tryHandleInput(2, options()[1], inputEvent)) {
			return;
		}
		if (tryHandleInput(3, options()[2], inputEvent)) {
			return;
		}

		// If the event was not handled and the focus is locked, cancel the event.
		if (FocusManager.get().isFocusLocked()) {
			inputEvent.preventDefault();
			inputEvent.stopImmediatePropagation();
		}
	};

	const onNavigate = (navigationEvent: NavigateInputEvent) => {
		if (navigationEvent.detail.status != InputActionStatuses.FINISH) {
			return;
		}

		if (focusCtx()?.navigate(navigationEvent.detail.navigation)) {
			navigationEvent.preventDefault();
			navigationEvent.stopPropagation();
		}
	};

	const tryHandleInput = (
		optionNum: number,
		calloutOptionDef: TutorialCalloutOptionDefinition | undefined,
		inputEvent: InputEngineEvent,
	) => {
		if (calloutOptionDef) {
			const gamepadActionName: string | undefined = FxsNavHelp.getGamepadActionName(
				calloutOptionDef.actionKey.toLowerCase(),
			);
			if (gamepadActionName != undefined && inputEvent.detail.name == gamepadActionName) {
				inputEvent.stopPropagation();
				inputEvent.preventDefault();
				if (calloutOptionDef.closes && !isClosed()) {
					setSelectedOptionNum(optionNum);
					setNextID(calloutOptionDef.nextID || "");
					close();
				}

				return true; // even when there is no callback
			} // Else the input event is not for that option
		} // Else the option is not available

		return false;
	};

	const lockFocus = (focus: string) => {
		if ((!focusManager.isFocusLocked() && isInspecting() && currentFocus != focus) || currentFocus == focus) {
			setFocusSet(focusManager.lockFocus(focusManager.currentFocus(), "tutorial-callout", "change of focus"));
			ViewManager.getHarness()?.classList.remove("trigger-nav-help");
		}
	};

	const unlockFocus = (focus: string) => {
		if (focusManager.isFocusLocked() && currentFocus == focus) {
			setFocusSet(!focusManager.unlockFocus(focusManager.currentFocus(), "tutorial-callout"));
		}
	};

	createEffect(
		on(
			tooltipModel.locked,
			(currentLocked) => {
				if (currentLocked != undefined) {
					setIsInspecting(true);
				} else {
					setIsInspecting(false);
				}
			},
			{ defer: true },
		),
	);

	createEffect(
		on(
			isInspecting,
			(inspecting: boolean) => {
				if (inspecting) {
					setIsTooltipInputChange(true);
					if (hasTooltips()) {
						// we want to have the input context for correct tooltip navigation
						Input.setActiveContext(InputContext.Shell);
						ViewManager.getHarness()?.classList.remove("trigger-nav-help");

						// Focus on the tooltips content
						unlockFocus("buttons");
						focusManager.setFocus(slotBody);
						currentFocus = "body";
					}
				} else {
					if (hasOptions()) {
						Input.setActiveContext(ViewManager.current.getInputContext());

						focusManager.setFocus(buttons);
						currentFocus = "buttons";
						lockFocus("buttons");
					} else {
						// If there's no option and we were inspecting, then try to regain interactability on the screen.
						tryRegainFocus();
					}
					delayByFrame(() => {
						// the manager needs to know we are inspecting (outside solid signals)
						// and needs to know the context change is not nested tooltip related
						setIsTooltipInputChange(false);
					}, 3);
				}
			},
			{ defer: true },
		),
	);

	onMount(() => {
		window.addEventListener("engine-input", onEngineInput);
		window.addEventListener("navigate-input", onNavigateInput);

		window.addEventListener(ActiveDeviceTypeChangedEventName, onActiveDeviceChanged, true);
		window.addEventListener(TutorialCalloutMinimizeEventName, onCalloutMinimizeToggle);
		window.addEventListener(TutorialCalloutInspectEventName, onCalloutInspect);

		engine.on(ContextManagerEvents.OnChanged, onContextChanged);
		engine.trigger("TutorialCallout");

		SetIsPlotTooltipVisible(false);

		if (!isWatchOut()) {
			audioTrigger("popup-open");
		} else {
			useAudio("AdvisorWatchoutPopup")("popup-open");
		}
	});

	onCleanup(() => {
		window.removeEventListener(TutorialCalloutInspectEventName, onCalloutInspect);
		window.removeEventListener(TutorialCalloutMinimizeEventName, onCalloutMinimizeToggle);
		window.removeEventListener(ActiveDeviceTypeChangedEventName, onActiveDeviceChanged, true);
		window.removeEventListener("navigate-input", onNavigateInput);
		window.removeEventListener("engine-input", onEngineInput);

		engine.off(ContextManagerEvents.OnChanged, onContextChanged);
		engine.trigger("TutorialCallout");

		SetIsPlotTooltipVisible(true);
		tryRegainFocus();

		if (!isWatchOut()) {
			audioTrigger("popup-close");
		} else {
			useAudio("AdvisorWatchoutPopup")("popup-close");
		}
	});

	const tryRegainFocus = () => {
		// If there's a screen below the tutorials (top of ContextManager) try to regain the focus on that screen
		const currentTarget = ContextManager.getCurrentTarget();
		if (!currentTarget) {
			ViewManager.handleReceiveFocus();
			return;
		}

		// set context and receive focus for legacy screens
		const panel = (currentTarget as ComponentRoot<Panel>).component;
		if (panel.inputContext != null && panel.inputContext != InputContext.INVALID) {
			Input.setActiveContext(panel.inputContext);
			panel.onReceiveFocus();
		} else {
			// set focus for solid screens
			FocusManager.get().setFocus(currentTarget);
		}
	};

	const close = () => {
		if (isClosed()) {
			console.error(
				"tutorial-callout: close(): Tutorial callout being closed when already marked closed. id: ",
				id(),
			);
		}

		window.dispatchEvent(
			new LowerCalloutEvent({
				itemID: id(),
				optionNum: selectedOptionNum() as 1 | 2 | 3,
				nextID: nextID(),
				closed: true,
			}),
		);

		setIsClosed(true);
		setFocusSet(false);
	};

	return (
		<>
			{/* Backdrop overlay similar to tooltips for the tutorial inspect */}
			<Show when={isInspecting()}>
				<Activatable
					onClick={() => {
						setIsInspecting(false);
					}}
					class="callout-backdrop fixed inset-0 pointer-events-auto"
					style={{
						"background-color": "rgba(0 0 0 / .5)",
					}}
					on:engine-input={(e: InputEngineEvent) => {
						if (e.detail.status === InputActionStatuses.FINISH && e.detail.name === "touch-tap") {
							e.stopPropagation();
							setIsInspecting(false);
						}
					}}
				/>
			</Show>
			<div
				ref={root}
				classList={{
					handheld: handheld(),
					"type--notification": isWatchOut(),
					"tutorial-callout_has-advisor":
						advisorURL() != "" && UI.getViewExperience() == UIViewExperience.Mobile,
					"track-input-change": isTooltipInputChange(),
				}}
				class="tutorial-callout-content absolute flex flex-col w-auto top-0 pointer-events-auto"
			>
				<div class="tutorial-callout-bg">
					<div
						style={{ "background-image": "url(blp:tutorial_Icon_header)" }}
						class="absolute bg-center bg-contain bg-no-repeat -top-7 w-full h-16"
					/>
					<div
						style={{ "background-image": "url(blp:mp_player_detail)" }}
						class="absolute size-4 bg-contain rotate-180 top-2 left-2"
					/>
					<Show when={isMinimizeDisabled() || isMinimized() || isInspecting()}>
						<div
							style={{ "background-image": "url(blp:mp_player_detail)" }}
							class="absolute size-4 bg-contain -rotate-90 top-2 right-2"
						/>
					</Show>
					<div
						style={{ "background-image": "url(blp:mp_player_detail)" }}
						class="absolute size-4 bg-contain rotate-90 bottom-2 left-2"
					/>
					<div
						style={{ "background-image": "url(blp:mp_player_detail)" }}
						class="absolute size-4 bg-contain rotate-0 bottom-2 right-2"
					/>
				</div>
				<div
					class="tutorial-callout-body-advisor-topper absolute inset-0"
					classList={{
						hidden: advisorURL() == "",
					}}
				>
					<div class="relative w-full h-full">
						<div class="flex flex-row absolute">
							<div class="tutorial-callout-body-advisor-wrapper w-1\\/2 self-center" />
							<div class="tutorial-callout-body-advisor-wrapper w-1\\/2 self-center -scale-x-100" />
						</div>
						<div class="flex flex-row absolute self-center tutorial-callout-body-advisor-image-container">
							<div class="relative">
								<div class="tutorial-callout-body-advisor-bg bg-cover bg-no-repeat size-38" />
								<div
									class="tutorial-callout-body-advisor-image absolute inset-0"
									classList={{
										"no-advisor": advisorURL() == "",
									}}
									style={{ "background-image": `url('${advisorURL()}')` }}
								/>
							</div>
						</div>
					</div>
				</div>
				<AudioContextProvider segment="TutorialPopupMinimize">
					<MinusPlusButton
						class="callout-min-button absolute top-3 right-3"
						style={{
							display: isMinimizeDisabled() || isMinimized() || isInspecting() ? "none" : "flex",
						}}
						dataDisabled={isMinimizeDisabled()}
						onActivate={onCalloutMinimizeToggle}
						type="minus"
						hotkeyAction="center-plot-cursor"
					/>
				</AudioContextProvider>
				<Show when={title()}>
					<div
						class="tutorial-callout-title-container relative flex flex-col items-center h-auto mt-3"
						classList={{
							"mt-8": advisorURL() != "",
						}}
					>
						<div class="tutorial-callout-title fxs-header font-title-xl pointer-events-auto mb-0 mt-1\.5 relative justify-center text-center pb-2 -mr-1 tracking-100">
							<L10n.Stylize text={Locale.toUpper(title() || "")} />
						</div>
						<div
							style={{ "background-image": "url(blp:shell_small-filigree)" }}
							class="absolute w-96 h-14 bg-center bg-contain bg-no-repeat -bottom-7"
						/>
					</div>
				</Show>
				<Slot
					class="tutorial-callout-body"
					ref={slotBody}
					on:navigate-input={onNavigate}
					navRules={TooltipNavigationRules}
					lockNavigation
					tabIndex={-1}
				>
					{/* @ts-expect-error -- Typing issue with render functions, but this follows the style in the solidjs docs */}
					{() => {
						onMount(() => {
							const focusCtx = useFocusContext()!;
							// register the slot so we can shift focus to a non-keyword element which allows controllers to navigate to the previous tooltip
							focusCtx.register(slotBody);
							setFocusCtx(focusCtx);
						});

						onCleanup(() => {
							setFocusCtx(null);
							unlockFocus("buttons");
						});

						return (
							<>
								<Show when={advisorType() != undefined}>
									<div class="tutorial-callout-body-advisor-container flex flex-row my-4 mx-2 items-center">
										<InnerFrame class="tutorial-callout-advisor-text relative ml-6 mr-4">
											<div class="advisor-text__content relative text-base text-primary-1 mt-3 mb-3 ml-6 mr-4">
												<L10n.Stylize text={advisorText() || ""} />
											</div>
										</InnerFrame>
									</div>
								</Show>
								<Show when={advisorType() == undefined}>
									<div class="tutorial-callout-body-text img-base-ticket-bg text-base mt-3 mb-3 ml-6 mr-4 py-5 px-3 pointer-events-auto">
										<L10n.Stylize text={bodyText() || ""} />
									</div>
								</Show>
							</>
						);
					}}
				</Slot>
				<HSlot
					ref={buttons}
					class="tutorial-callout-buttons flex flex-row justify-center flex-wrap gap-2"
					lockNavigation
					tabIndex={-1}
				>
					<Show
						when={
							!isTooltipInputChange() ||
							ActiveInputDevice() == InputDeviceType.Hybrid ||
							ActiveInputDevice() == InputDeviceType.Mouse ||
							ActiveInputDevice() == InputDeviceType.Keyboard
						}
					>
						<For each={options()}>
							{(option, index) => (
								<CalloutOption
									order={index() + 1}
									definition={option}
									onInteraction={onOptionInteraction}
									onActivate={onOptionActivate}
								/>
							)}
						</For>
					</Show>
				</HSlot>
				<div class="tutorial-callout-overlay" />
				<Show when={hasTooltips() && !isMinimized()}>
					<div class="relative flex items-center min-h-14">
						<Tooltip.InspectHint handlers={{ isLocked, isTopLevelActiveAndLocked, tooltipCount }} />
					</div>
				</Show>
				<div class="tutorial-callout-minimized flex-col items-center">
					<div class="tutorial-callout-min__advisor-image" />
					<AudioContextProvider segment="TutorialMinimized">
						<Button
							class="tutorial-callout-min__button mb-2"
							hotkeyAction="center-plot-cursor"
							onActivate={onCalloutMinimizeToggle}
						>
							<NavHelp class="relative mr-2" />
							{maximizeCaption()}
						</Button>
					</AudioContextProvider>
				</div>
			</div>
		</>
	);
};

ComponentUtilities.loadStyles(style);

// Register the legacy wrapper component
defineLegacyComponent(
	"tutorial-callout",
	{
		classNames: ["relative", "size-full"],
		attrs: {
			itemID: "",
			value: "",
		},
	},
	(attrs, el) => {
		return (
			<TutorialCallout
				attrs={attrs}
				el={el!}
			/>
		);
	},
);
